import java.util.*;
import java.util.concurrent.*;

public class Main {
    public static void main(String[] args)
            throws Exception {
        List<Future<Integer>> fs =
            new ArrayList<>();
        try (var ex = Executors
              .newVirtualThreadPerTaskExecutor()) {
            for (int i = 1; i <= 3; i++) {
                int n = i;
                fs.add(ex.submit(() -> n * n));
            }
        }
        int sum = 0;
        for (var f : fs) sum += f.get();
        Thread t = Thread.ofVirtual()
            .unstarted(() -> {});
        System.out.println(sum + " "
            + t.isDaemon() + " " + t.getState());
    }
}

